def solve(M):
    n=len(M); T={'tl':M,'tr':r90(M),'bl':r270(M),'br':r180(M)}
    res=[]
    for i in range(2*n):
        row=[]
        for j in range(2*n):
            if i<n and j<n: row.append(T['tl'][i][j])
            elif i<n: row.append(T['tr'][i][j-n])
            elif j<n: row.append(T['bl'][i-n][j])
            else: row.append(T['br'][i-n][j-n])
        res.append(row)
    return res
